choose.otherwise:
update cms_topic_cancellation_receipt set receipt_json=#{receipt}
where topic_id=#{id} and cancellation_epoch=#{epoch} and request_hash=#{requestHash}
and JSON_UNQUOTE(JSON_EXTRACT(receipt_json, '$.state'))='PENDING'
and JSON_UNQUOTE(JSON_EXTRACT(receipt_json, '$.requestHash'))=#{requestHash}

mapper.select:
select club_id as clubId, count(*) as topicCount from cms_topic where del_flag = 0 and status = 1 and user_status = 1 and club_id in
#{clubId}
and (end_date is null or end_date >= #{now}) group by club_id

select id, end_date from cms_topic
where id in #{id}
where 1 = 0

mapper.update:
update cms_topic
   set circle_reviewed_at = null, update_time = #{updateTime}
 where id = #{id} and circle_theme_code is not null and is_template = 0 and del_flag = 0

update cms_topic
set lifecycle = #{target}, update_time = #{updateTime}
where id = #{id} and lifecycle = #{expected} and del_flag = 0

update cms_topic
set club_coop_open = #{clubCoopOpen},
    club_pinned = #{clubPinned},
    club_member_only = #{clubMemberOnly}
where id = #{topicId} and club_id = #{clubId}

update cms_topic set status = 0, check_status = 0, user_status = 0
where id = #{id} and del_flag = 0
  and status = #{fromStatus} and check_status = #{fromCheckStatus}
  and config_version = #{configVersion}
